var SpeedGateManager = class {
  scene;
  biomes;
  random = Math.random;
  gates = [];
  nextGateZ = 60;
  gateSpacing = 80;
  // meters between gates
  activeBoost = 0;
  // remaining boost time
  boostSpeed = 0;
  // current boost speed addition
  cleanupTimer = 0;
  /** Replace the PRNG used for gate spawning. Call before each game start. */
  setRandom(fn) {
    this.random = fn;
  }
  constructor(scene, biomes) {
    this.scene = scene;
    this.biomes = biomes;
  }
  update(dt2, playerZ, playerX) {
    let justCollected = false;
    let boostAmount = 0;
    let gatePosition = null;
    while (this.nextGateZ < playerZ + 80) {
      this.spawnGate(this.nextGateZ);
      this.nextGateZ += this.gateSpacing + (this.random() - 0.5) * 20;
    }
    const time = performance.now() * 1e-3;
    for (const gate of this.gates) {
      if (!gate.active) continue;
      gate.ring.rotation.z += dt2 * 3;
      gate.ring.rotation.x += dt2 * 0.5;
      const positions = gate.particles.geometry.getAttribute("position");
      for (let i = 0; i < positions.count; i++) {
        const angle = time * 4 + i / positions.count * Math.PI * 2;
        const radius = 1.2 + Math.sin(time * 2 + i) * 0.3;
        positions.setXYZ(
          i,
          Math.cos(angle) * radius,
          Math.sin(angle) * radius,
          Math.sin(time * 3 + i * 0.5) * 0.3
        );
      }
      positions.needsUpdate = true;
      const dist = Math.abs(playerZ - gate.z);
      if (dist < 15) {
        const proximity = 1 - dist / 15;
        const mat = gate.ring.material;
        mat.emissiveIntensity = 0.6 + proximity * 0.8;
        gate.group.scale.setScalar(1 + proximity * 0.1);
      }
      if (!gate.collected) {
        const dz = Math.abs(playerZ - gate.z);
        const dx = Math.abs(playerX - gate.x);
        if (dz < 1.5 && dx < 2) {
          gate.collected = true;
          justCollected = true;
          boostAmount = gate.boostAmount;
          gatePosition = new Vector3(gate.x, 1, gate.z);
          gate.ring.scale.setScalar(3);
          const mat = gate.ring.material;
          mat.opacity = 0.3;
        }
      }
      if (gate.z < playerZ - 10) {
        gate.active = false;
        gate.group.visible = false;
      }
    }
    if (this.activeBoost > 0) {
      this.activeBoost -= dt2;
      if (this.activeBoost <= 0) {
        this.boostSpeed = 0;
      }
    }
    this.cleanupTimer += dt2;
    if (this.cleanupTimer > 5) {
      this.cleanupTimer = 0;
      this.cleanup();
    }
    return { justCollected, boostAmount, gatePosition };
  }
  /** Apply a speed boost */
  applyBoost(amount) {
    this.boostSpeed = amount;
    this.activeBoost = 2.5;
  }
  /** Get current boost speed addition */
  getBoostSpeed() {
    if (this.activeBoost <= 0) return 0;
    const t = this.activeBoost / 2.5;
    return this.boostSpeed * t;
  }
  /** Whether currently boosting */
  isBoosting() {
    return this.activeBoost > 0;
  }
  spawnGate(z) {
    const x2 = (this.random() - 0.5) * 4;
    const group = new Group();
    group.position.set(x2, 1, z);
    const c = this.biomes.colors;
    const gateColor = 65535;
    const torusGeo = new TorusGeometry(1.5, 0.08, 8, 32);
    const torusMat = new MeshStandardMaterial({
      color: gateColor,
      emissive: gateColor,
      emissiveIntensity: 0.6,
      metalness: 0.8,
      roughness: 0.1,
      transparent: true,
      opacity: 0.9
    });
    const ring = new Mesh(torusGeo, torusMat);
    group.add(ring);
    const outerGeo = new TorusGeometry(1.8, 0.04, 6, 32);
    const outerMat = new MeshStandardMaterial({
      color: gateColor,
      emissive: gateColor,
      emissiveIntensity: 0.3,
      transparent: true,
      opacity: 0.5
    });
    const outerRing = new Mesh(outerGeo, outerMat);
    outerRing.rotation.z = Math.PI / 6;
    group.add(outerRing);
    const particleCount = 20;
    const positions = new Float32Array(particleCount * 3);
    const particleGeo = new BufferGeometry();
    particleGeo.setAttribute("position", new BufferAttribute(positions, 3));
    const particleMat = new PointsMaterial({
      color: gateColor,
      size: 0.12,
      transparent: true,
      opacity: 0.8,
      blending: AdditiveBlending,
      depthWrite: false
    });
    const particles = new Points(particleGeo, particleMat);
    group.add(particles);
    for (let i = 0; i < 4; i++) {
      const angle = i / 4 * Math.PI * 2;
      const arrowGeo = new ConeGeometry(0.12, 0.3, 4);
      const arrowMat = new MeshBasicMaterial({
        color: gateColor,
        transparent: true,
        opacity: 0.6,
        blending: AdditiveBlending
      });
      const arrow = new Mesh(arrowGeo, arrowMat);
      arrow.position.set(Math.cos(angle) * 1.2, Math.sin(angle) * 1.2, 0);
      arrow.rotation.z = angle + Math.PI / 2;
      group.add(arrow);
    }
    this.scene.add(group);
    const boostAmount = 10 + Math.min(z / 200, 15);
    this.gates.push({
      group,
      z,
      x: x2,
      active: true,
      collected: false,
      ring,
      particles,
      boostAmount
    });
  }
  cleanup() {
    for (let i = this.gates.length - 1; i >= 0; i--) {
      if (!this.gates[i].active) {
        const gate = this.gates[i];
        this.scene.remove(gate.group);
        gate.group.traverse((child) => {
          if (child instanceof Mesh) {
            child.geometry.dispose();
            child.material.dispose();
          }
          if (child instanceof Points) {
            child.geometry.dispose();
            child.material.dispose();
          }
        });
        this.gates.splice(i, 1);
      }
    }
  }
  reset() {
    for (const gate of this.gates) {
      this.scene.remove(gate.group);
      gate.group.traverse((child) => {
        if (child instanceof Mesh) {
          child.geometry.dispose();
          child.material.dispose();
        }
        if (child instanceof Points) {
          child.geometry.dispose();
          child.material.dispose();
        }
      });
    }
    this.gates = [];
    this.nextGateZ = 60;
    this.activeBoost = 0;
    this.boostSpeed = 0;
  }
};

