var UnlockManager = class {
  selectedTrail;
  selectedCrystal;
  constructor() {
    this.selectedTrail = localStorage.getItem("shatterDriftTrail") || "default";
    this.selectedCrystal = localStorage.getItem("shatterDriftCrystal") || "default";
  }
  getSelectedTrail() {
    return TRAIL_STYLES[this.selectedTrail] || TRAIL_STYLES.default;
  }
  getSelectedCrystal() {
    return CRYSTAL_SKINS[this.selectedCrystal] || CRYSTAL_SKINS.default;
  }
  selectTrail(id) {
    if (TRAIL_STYLES[id]) {
      this.selectedTrail = id;
      localStorage.setItem("shatterDriftTrail", id);
    }
  }
  selectCrystal(id) {
    if (CRYSTAL_SKINS[id]) {
      this.selectedCrystal = id;
      localStorage.setItem("shatterDriftCrystal", id);
    }
  }
  /** Get the current trail color, accounting for rainbow/time effects */
  getTrailColor(time) {
    const style = this.getSelectedTrail();
    if (style.rainbow) {
      const hue = time * 0.2 % 1;
      return hslToHex(hue, 1, 0.5);
    }
    if (style.color2) {
      const t = (Math.sin(time * 3) + 1) / 2;
      return lerpColor(style.color, style.color2, t);
    }
    return style.color;
  }
  getTrailSize() {
    return this.getSelectedTrail().size ?? 1;
  }
};
function hslToHex(h, s, l) {
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x2 = c * (1 - Math.abs(h * 6 % 2 - 1));
  const m = l - c / 2;
  let r = 0, g = 0, b2 = 0;
  if (h < 1 / 6) {
    r = c;
    g = x2;
  } else if (h < 2 / 6) {
    r = x2;
    g = c;
  } else if (h < 3 / 6) {
    g = c;
    b2 = x2;
  } else if (h < 4 / 6) {
    g = x2;
    b2 = c;
  } else if (h < 5 / 6) {
    r = x2;
    b2 = c;
  } else {
    r = c;
    b2 = x2;
  }
  return Math.round((r + m) * 255) << 16 | Math.round((g + m) * 255) << 8 | Math.round((b2 + m) * 255);
}
function lerpColor(a, b2, t) {
  const ar = a >> 16 & 255, ag = a >> 8 & 255, ab = a & 255;
  const br = b2 >> 16 & 255, bg = b2 >> 8 & 255, bb = b2 & 255;
  return Math.round(ar + (br - ar) * t) << 16 | Math.round(ag + (bg - ag) * t) << 8 | Math.round(ab + (bb - ab) * t);
}

// src/afterimage.ts
var MAX_GHOSTS = 8;
var GHOST_INTERVAL = 0.04;
var GHOST_LIFETIME = 0.35;
var AfterimageTrail = class {
  ghosts = [];
  pool = [];
  scene;
  geo;
  spawnTimer = 0;
  intensity = 0;
  // 0–1 driven by speed
  constructor(scene) {
    this.scene = scene;
    this.geo = new IcosahedronGeometry(0.6, 0);
    for (let i = 0; i < MAX_GHOSTS; i++) {
      const mat = new MeshBasicMaterial({
        color: 65484,
        transparent: true,
        opacity: 0,
        blending: AdditiveBlending,
        depthWrite: false,
        wireframe: true
      });
      const mesh = new Mesh(this.geo, mat);
      mesh.visible = false;
      scene.add(mesh);
      this.pool.push(mesh);
    }
  }
  /** Set intensity from speed (0 = none, 1 = full) */
  setIntensity(speedNorm) {
    this.intensity = Math.max(0, (speedNorm - 0.4) / 0.6);
  }
  /** Set color to match biome/state */
  setColor(color) {
    for (const mesh of this.pool) {
      mesh.material.color.setHex(color);
    }
  }
  /** Spawn a ghost at the given position + rotation */
  spawn(position, rotation) {
    let mesh = null;
    for (const m of this.pool) {
      if (!m.visible) {
        mesh = m;
        break;
      }
    }
    if (!mesh) {
      if (this.ghosts.length > 0) {
        const old = this.ghosts.shift();
        mesh = old.mesh;
      } else return;
    }
    mesh.visible = true;
    mesh.position.copy(position);
    mesh.rotation.copy(rotation);
    mesh.scale.setScalar(1);
    mesh.material.opacity = 0.4 * this.intensity;
    this.ghosts.push({
      mesh,
      life: GHOST_LIFETIME,
      maxLife: GHOST_LIFETIME,
      baseScale: 1
    });
  }
  update(dt2, playerPos, playerRotation, isShattered) {
    if (this.intensity < 0.01) {
      for (const ghost of this.ghosts) {
        ghost.mesh.visible = false;
      }
      this.ghosts.length = 0;
      return;
    }
    this.spawnTimer -= dt2;
    if (this.spawnTimer <= 0) {
      this.spawnTimer = GHOST_INTERVAL / this.intensity;
      if (!isShattered) {
        this.spawn(playerPos, playerRotation);
      }
    }
    for (let i = this.ghosts.length - 1; i >= 0; i--) {
      const g = this.ghosts[i];
      g.life -= dt2;
      const t = g.life / g.maxLife;
      const mat = g.mesh.material;
      mat.opacity = t * 0.35 * this.intensity;
      g.mesh.scale.setScalar(g.baseScale * (0.6 + t * 0.4));
      if (g.life <= 0) {
        g.mesh.visible = false;
        this.ghosts.splice(i, 1);
      }
    }
  }
  dispose() {
    for (const mesh of this.pool) {
      this.scene.remove(mesh);
      mesh.material.dispose();
    }
    this.geo.dispose();
  }
};

// src/ribbon.ts
var MAX_POINTS = 60;
var POINT_LIFETIME = 0.8;
var RibbonTrail = class {
  points = [];
  mesh;
  geometry;
  material;
  positions;
  alphas;
  scene;
  enabled = true;
  constructor(scene) {
    this.scene = scene;
    const vertexCount = MAX_POINTS * 2;
    this.positions = new Float32Array(vertexCount * 3);
    this.alphas = new Float32Array(vertexCount);
    this.geometry = new BufferGeometry();
    this.geometry.setAttribute("position", new BufferAttribute(this.positions, 3));
    this.geometry.setAttribute("alpha", new BufferAttribute(this.alphas, 1));
    const indices = [];
    for (let i = 0; i < MAX_POINTS - 1; i++) {
      const a = i * 2;
      const b2 = i * 2 + 1;
      const c = (i + 1) * 2;
      const d = (i + 1) * 2 + 1;
      indices.push(a, b2, c);
      indices.push(b2, d, c);
    }
    this.geometry.setIndex(indices);
    this.material = new ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: AdditiveBlending,
      side: DoubleSide,
      uniforms: {
        uColor: { value: new Color(65484) },
        uOpacity: { value: 0.5 },
        uTime: { value: 0 }
      },
      vertexShader: (
        /* glsl */
        `
        attribute float alpha;
        varying float vAlpha;
        varying vec2 vPos;

        void main() {
          vAlpha = alpha;
          vPos = position.xy;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `
      ),
      fragmentShader: (
        /* glsl */
        `
        uniform vec3 uColor;
        uniform float uOpacity;
        uniform float uTime;
        varying float vAlpha;
        varying vec2 vPos;

        void main() {
          // Core glow \u2014 brighter at center, fading at edges
          float glow = vAlpha * uOpacity;

          // Subtle energy pulse
          float pulse = 0.9 + 0.1 * sin(vPos.y * 0.5 + uTime * 5.0);
          glow *= pulse;

          // Color with slight white core
          vec3 col = mix(uColor, vec3(1.0), vAlpha * 0.3);

          gl_FragColor = vec4(col, glow);
        }
      `
      )
    });
    this.mesh = new Mesh(this.geometry, this.material);
    this.mesh.frustumCulled = false;
    scene.add(this.mesh);
  }
  setColor(color) {
    this.material.uniforms.uColor.value.setHex(color);
  }
  setEnabled(v3) {
    this.enabled = v3;
    this.mesh.visible = v3;
  }
  setOpacity(v3) {
    this.material.uniforms.uOpacity.value = v3;
  }
  addPoint(worldPos, width = 0.3) {
    if (!this.enabled) return;
    this.points.unshift({
      position: worldPos.clone(),
      age: 0,
      width
    });
    if (this.points.length > MAX_POINTS) {
      this.points.length = MAX_POINTS;
    }
  }
  update(dt2) {
    this.material.uniforms.uTime.value += dt2;
    for (let i = this.points.length - 1; i >= 0; i--) {
      this.points[i].age += dt2;
      if (this.points[i].age > POINT_LIFETIME) {
        this.points.splice(i, 1);
      }
    }
    const up = new Vector3(0, 1, 0);
    const posAttr = this.geometry.getAttribute("position");
    const alphaAttr = this.geometry.getAttribute("alpha");
    for (let i = 0; i < MAX_POINTS; i++) {
      const idx = i * 2;
      if (i < this.points.length) {
        const p = this.points[i];
        const t = 1 - p.age / POINT_LIFETIME;
        const taper = t * (1 - i / this.points.length * 0.5);
        let dir;
        if (i < this.points.length - 1) {
          dir = new Vector3().subVectors(this.points[i + 1].position, p.position).normalize();
        } else if (i > 0) {
          dir = new Vector3().subVectors(p.position, this.points[i - 1].position).normalize();
        } else {
          dir = new Vector3(0, 0, 1);
        }
        const perp = new Vector3().crossVectors(dir, up).normalize();
        const halfWidth = p.width * taper;
        this.positions[idx * 3] = p.position.x - perp.x * halfWidth;
        this.positions[idx * 3 + 1] = p.position.y - perp.y * halfWidth;
        this.positions[idx * 3 + 2] = p.position.z - perp.z * halfWidth;
        this.alphas[idx] = taper;
        this.positions[(idx + 1) * 3] = p.position.x + perp.x * halfWidth;
        this.positions[(idx + 1) * 3 + 1] = p.position.y + perp.y * halfWidth;
        this.positions[(idx + 1) * 3 + 2] = p.position.z + perp.z * halfWidth;
        this.alphas[idx + 1] = taper;
      } else {
        this.positions[idx * 3 + 1] = -100;
        this.positions[(idx + 1) * 3 + 1] = -100;
        this.alphas[idx] = 0;
        this.alphas[idx + 1] = 0;
      }
    }
    posAttr.needsUpdate = true;
    alphaAttr.needsUpdate = true;
    this.geometry.computeBoundingSphere();
  }
  dispose() {
    this.scene.remove(this.mesh);
    this.geometry.dispose();
    this.material.dispose();
  }
};

// src/stats.ts
var STORAGE_KEY = "shatterDriftRunHistory";
var MAX_HISTORY = 50;
var RunHistoryTracker = class {
  history = [];
  constructor() {
    this.load();
  }
  load() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        this.history = JSON.parse(raw);
      }
    } catch {
      this.history = [];
    }
  }
  save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.history));
    } catch {
      this.history = this.history.slice(-20);
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(this.history));
      } catch {
      }
    }
  }
  /** Record a completed run */
  recordRun(run) {
    const comparison = this.compare(run);
    this.history.push(run);
    if (this.history.length > MAX_HISTORY) {
      this.history = this.history.slice(-MAX_HISTORY);
    }
    this.save();
    return comparison;
  }
  /** Compare a run against history */
  compare(run) {
    if (this.history.length === 0) {
      return {
        isFirstRun: true,
        newBestScore: true,
        newBestDistance: true,
        newBestCombo: true,
        newBestSpeed: true,
        newBestBiome: true,
        improvementPct: 0,
        previousBest: null,
        averageScore: 0,
        runNumber: 1,
        bestStreak: 0
      };
    }
    const bestScore = Math.max(...this.history.map((r) => r.score));
    const bestDistance = Math.max(...this.history.map((r) => r.distance));
    const bestCombo = Math.max(...this.history.map((r) => r.maxCombo));
    const bestSpeed = Math.max(...this.history.map((r) => r.topSpeed));
    const bestBiome = Math.max(...this.history.map((r) => r.biomeIndex));
    const avgScore = this.history.reduce((s, r) => s + r.score, 0) / this.history.length;
    let bestStreak = 0;
    for (let i = this.history.length - 1; i > 0; i--) {
      if (this.history[i].score > this.history[i - 1].score) {
        bestStreak++;
      } else break;
    }
    return {
      isFirstRun: false,
      newBestScore: run.score > bestScore,
      newBestDistance: run.distance > bestDistance,
      newBestCombo: run.maxCombo > bestCombo,
      newBestSpeed: run.topSpeed > bestSpeed,
      newBestBiome: run.biomeIndex > bestBiome,
      improvementPct: bestScore > 0 ? Math.round((run.score - bestScore) / bestScore * 100) : 0,
      previousBest: bestScore,
      averageScore: Math.round(avgScore),
      runNumber: this.history.length + 1,
      bestStreak: run.score > (this.history[this.history.length - 1]?.score || 0) ? bestStreak + 1 : 0
    };
  }
  /** Get summary stats for display */
  getSummary() {
    if (this.history.length === 0) {
      return { totalRuns: 0, bestScore: 0, bestDistance: 0, avgScore: 0, bestGrade: "\u2014", recentTrend: "neutral" };
    }
    const bestScore = Math.max(...this.history.map((r) => r.score));
    const bestDistance = Math.max(...this.history.map((r) => r.distance));
    const avgScore = Math.round(this.history.reduce((s, r) => s + r.score, 0) / this.history.length);
    const gradeRanks = ["E RANK", "D RANK", "C RANK", "B RANK", "A RANK", "S RANK"];
    const bestGradeIdx = Math.max(...this.history.map((r) => gradeRanks.indexOf(r.grade)));
    const bestGrade = bestGradeIdx >= 0 ? gradeRanks[bestGradeIdx] : "\u2014";
    let recentTrend = "neutral";
    if (this.history.length >= 6) {
      const recent5 = this.history.slice(-5).reduce((s, r) => s + r.score, 0) / 5;
      const prior5 = this.history.slice(-10, -5).reduce((s, r) => s + r.score, 0) / Math.min(5, this.history.slice(-10, -5).length);
      if (recent5 > prior5 * 1.1) recentTrend = "up";
      else if (recent5 < prior5 * 0.9) recentTrend = "down";
    }
    return { totalRuns: this.history.length, bestScore, bestDistance, avgScore, bestGrade, recentTrend };
  }
  getBestDistance() {
    if (this.history.length === 0) {
      return 0;
    }
    return Math.max(...this.history.map((run) => run.distance));
  }
  getSkillFactor() {
    const runCount = this.history.length;
    if (runCount < 3) {
      return 0.85;
    }
    if (runCount >= 10) {
      const averageDistance = this.history.reduce((sum, run) => sum + run.distance, 0) / runCount;
      if (averageDistance > 1200) {
        return 1.05;
      }
    }
    return 1;
  }
};

