function pickRandomContracts(count) {
  let pool = [...CONTRACT_POOL];
  const picked = [];
  for (let i = 0; i < count && pool.length > 0; i += 1) {
    const idx = Math.floor(Math.random() * pool.length);
    const [def] = pool.splice(idx, 1);
    picked.push({ def, progress: 0, complete: false, celebrateTimer: 0 });
    pool = pool.filter((p) => p.category !== def.category);
  }
  return picked;
}
function formatContractProgress(instance) {
  const { def, progress } = instance;
  if (def.format) {
    return def.format(progress, def.target);
  }
  return `${Math.min(Math.floor(progress), def.target)}/${def.target}`;
}
var ContractHUD = class {
  container;
  rows = [];
  labelEls = [];
  progressEls = [];
  boxEls = [];
  constructor() {
    this.container = document.createElement("div");
    this.container.id = "contract-hud";
    this.container.style.cssText = [
      "position:fixed",
      "top:72px",
      "left:28px",
      "display:flex",
      "flex-direction:column",
      "gap:6px",
      "pointer-events:none",
      "z-index:20",
      "opacity:0",
      "transition:opacity 0.3s"
    ].join(";");
    document.body.appendChild(this.container);
    for (let i = 0; i < 3; i++) {
      const row = document.createElement("div");
      row.style.cssText = [
        "display:flex",
        "align-items:center",
        "gap:5px",
        "font-family:'Orbitron',monospace",
        "font-size:9px",
        "letter-spacing:1px",
        "color:#556677",
        "transition:color 0.25s,text-shadow 0.25s"
      ].join(";");
      const box = document.createElement("span");
      box.textContent = "\u25A2";
      box.style.cssText = "flex-shrink:0;transition:color 0.25s,text-shadow 0.25s";
      const label = document.createElement("span");
      label.style.cssText = "transition:text-decoration 0.1s";
      const dot = document.createElement("span");
      dot.textContent = "\xB7";
      dot.style.cssText = "flex-shrink:0;opacity:0.5";
      const prog = document.createElement("span");
      prog.style.cssText = "opacity:0.8";
      row.appendChild(box);
      row.appendChild(label);
      row.appendChild(dot);
      row.appendChild(prog);
      this.container.appendChild(row);
      this.rows.push(row);
      this.labelEls.push(label);
      this.progressEls.push(prog);
      this.boxEls.push(box);
    }
  }
  show() {
    this.container.style.opacity = "1";
  }
  hide() {
    this.container.style.opacity = "0";
  }
  render(contracts) {
    for (let i = 0; i < 3; i++) {
      const inst = contracts[i];
      if (!inst) continue;
      const isCelebrating = inst.complete && inst.celebrateTimer > 0;
      const isDimmed = inst.complete && inst.celebrateTimer <= 0;
      if (isCelebrating) {
        this.boxEls[i].textContent = "\u25A3";
        this.boxEls[i].style.color = "#00ffcc";
        this.boxEls[i].style.textShadow = "0 0 8px rgba(0,255,204,0.8)";
        this.rows[i].style.color = "#00ffcc";
        this.rows[i].style.textShadow = "0 0 6px rgba(0,255,204,0.4)";
        this.rows[i].style.opacity = "1";
        this.labelEls[i].style.textDecoration = "line-through";
        this.labelEls[i].textContent = inst.def.label;
        this.progressEls[i].textContent = "DONE";
      } else if (isDimmed) {
        this.boxEls[i].textContent = "\u25A3";
        this.boxEls[i].style.color = "#2a3a44";
        this.boxEls[i].style.textShadow = "none";
        this.rows[i].style.color = "#2a3a44";
        this.rows[i].style.textShadow = "none";
        this.rows[i].style.opacity = "0.4";
        this.labelEls[i].style.textDecoration = "line-through";
        this.labelEls[i].textContent = inst.def.label;
        this.progressEls[i].textContent = "DONE";
      } else {
        this.boxEls[i].textContent = "\u25A2";
        this.boxEls[i].style.color = "#556677";
        this.boxEls[i].style.textShadow = "none";
        this.rows[i].style.color = "#556677";
        this.rows[i].style.textShadow = "none";
        this.rows[i].style.opacity = "1";
        this.labelEls[i].style.textDecoration = "none";
        this.labelEls[i].textContent = inst.def.label;
        this.progressEls[i].textContent = formatContractProgress(inst);
      }
    }
  }
  dispose() {
    this.container.remove();
  }
};

// src/leaderboard.ts
var API_URL = "https://api.tommyato.com";
async function fetchLeaderboard(limit = 10, options) {
  try {
    let url;
    if (options?.mode === "daily" && options.date) {
      url = `${API_URL}/daily-scores?date=${options.date}&limit=${limit}`;
    } else {
      url = `${API_URL}/scores?limit=${limit}`;
    }
    const res = await fetch(url, { signal: AbortSignal.timeout(4e3) });
    if (!res.ok) return [];
    const data = await res.json();
    return data.scores || [];
  } catch {
    return [];
  }
}
async function submitScore(entry, options) {
  try {
    const isDaily = options?.mode === "daily" && options.date;
    const endpoint = isDaily ? `${API_URL}/daily-scores` : `${API_URL}/scores`;
    const body = isDaily ? { ...entry, date: options.date } : entry;
    const res = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(4e3)
    });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}
async function fetchGhosts(limit = 3) {
  try {
    const res = await fetch(`${API_URL}/games/shatter-drift/ghosts?limit=${limit}`, {
      signal: AbortSignal.timeout(5e3)
    });
    if (!res.ok) return [];
    const data = await res.json();
    return data.ghosts || [];
  } catch {
    return [];
  }
}
async function submitGhost(entry) {
  try {
    const res = await fetch(`${API_URL}/games/shatter-drift/ghosts`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(entry),
      signal: AbortSignal.timeout(8e3)
    });
    if (!res.ok) return null;
    const data = await res.json();
    return data.id || null;
  } catch {
    return null;
  }
}
async function fetchGhostUploadThreshold() {
  try {
    const scores = await fetchLeaderboard(10);
    if (scores.length < 10) return 0;
    const sorted = scores.slice().sort((a, b2) => b2.score - a.score);
    return sorted[9]?.score || 0;
  } catch {
    return 0;
  }
}

// src/ghost.ts
var GhostRecorder = class {
  frames = [];
  startTime = 0;
  lastSampleTime = 0;
  recording = false;
  /** 10Hz = 100ms between samples */
  sampleInterval = 100;
  start() {
    this.frames = [];
    this.startTime = performance.now();
    this.lastSampleTime = this.startTime - this.sampleInterval;
    this.recording = true;
  }
  stop() {
    this.recording = false;
  }
  /** Sample player state if the interval has elapsed. */
  sample(x2, z, speed, isShattered) {
    if (!this.recording) return;
    const now = performance.now();
    if (now - this.lastSampleTime < this.sampleInterval) return;
    this.lastSampleTime = now;
    this.frames.push({
      x: Math.round(x2 * 100) / 100,
      // 2 decimals — plenty for position
      z: Math.round(z * 100) / 100,
      speed: Math.round(speed * 10) / 10,
      shattered: isShattered ? 1 : 0,
      t: Math.round(now - this.startTime)
    });
  }
  getFrames() {
    return this.frames;
  }
  get frameCount() {
    return this.frames.length;
  }
};
var GHOST_COLORS = [
  { hex: 16777215, label: "white" },
  { hex: 16764006, label: "gold" },
  { hex: 13421772, label: "silver" }
];
var GHOST_OPACITY2 = 0.3;
var NAME_SPRITE_SCALE = 1.4;
var GhostManager = class {
  scene;
  ghosts = [];
  bursts = [];
  /** Run time in seconds since Playing state started. */
  runTime = 0;
  enabled = true;
  /** Names of ghosts that the player has outlasted this run (reset each run). */
  beatenNames = [];
  constructor(scene) {
    this.scene = scene;
  }
  setEnabled(enabled) {
    this.enabled = enabled;
    for (const g of this.ghosts) {
      g.group.visible = enabled && !g.finished;
    }
  }
  isEnabled() {
    return this.enabled;
  }
  get ghostCount() {
    return this.ghosts.length;
  }
  /** The loaded ghost records — used by Game to build the ghost pool for a race. */
  getRecords() {
    return this.ghosts.map((g) => g.record);
  }
  /** Populate ghosts from fetched records. Call before gameplay starts. */
  loadGhosts(records) {
    this.clear();
    for (let i = 0; i < Math.min(records.length, 3); i++) {
      const record = records[i];
      if (!record.frames || record.frames.length < 2) continue;
      const colorSpec = GHOST_COLORS[i % GHOST_COLORS.length];
      this.ghosts.push(this.createGhost(record, colorSpec.hex));
    }
    for (const g of this.ghosts) {
      g.group.visible = false;
      this.scene.add(g.group);
    }
  }
  createGhost(record, color) {
    const group = new Group();
    const geo = new IcosahedronGeometry(0.6, 0);
    const material = new MeshBasicMaterial({
      color,
      transparent: true,
      opacity: GHOST_OPACITY2,
      wireframe: true,
      depthWrite: false
    });
    const mesh = new Mesh(geo, material);
    group.add(mesh);
    const nameTexture = makeNameTexture(record.name, color);
    const nameMaterial = new SpriteMaterial({
      map: nameTexture,
      transparent: true,
      opacity: 0.7,
      depthTest: false,
      depthWrite: false
    });
    const nameSprite = new Sprite(nameMaterial);
    nameSprite.scale.set(NAME_SPRITE_SCALE * 4, NAME_SPRITE_SCALE * 0.5, 1);
    nameSprite.position.y = 1.2;
    group.add(nameSprite);
    group.visible = this.enabled;
    return {
      record,
      group,
      mesh,
      material,
      nameSprite,
      nameMaterial,
      color,
      finished: false,
      outlasted: false,
      fadeTimer: 0,
      lastFrameIdx: 0
    };
  }
  /** Reset run time and un-hide ghosts for a fresh run. */
  startRun() {
    this.runTime = 0;
    this.beatenNames = [];
    for (const g of this.ghosts) {
      g.finished = false;
      g.outlasted = false;
      g.fadeTimer = 0;
      g.lastFrameIdx = 0;
      g.material.opacity = GHOST_OPACITY2;
      g.nameMaterial.opacity = 0.7;
      g.group.visible = this.enabled;
    }
  }
  /** Advance ghost playback + bursts. Call every frame while Playing. */
  update(dt2) {
    this.runTime += dt2;
    const runTimeMs = this.runTime * 1e3;
    for (const g of this.ghosts) {
      if (g.finished) continue;
      const frames = g.record.frames;
      const last = frames[frames.length - 1];
      if (runTimeMs >= last.t) {
        if (!g.outlasted) {
          g.outlasted = true;
          g.fadeTimer = 0.6;
          this.beatenNames.push(g.record.name);
          this.spawnBurst(g.group.position, g.color);
        }
        g.fadeTimer -= dt2;
        const fade = Math.max(0, g.fadeTimer / 0.6);
        g.material.opacity = GHOST_OPACITY2 * fade;
        g.nameMaterial.opacity = 0.7 * fade;
        if (g.fadeTimer <= 0) {
          g.finished = true;
          g.group.visible = false;
        }
        continue;
      }
      let i = g.lastFrameIdx;
      while (i < frames.length - 2 && frames[i + 1].t <= runTimeMs) i++;
      g.lastFrameIdx = i;
      const a = frames[i];
      const b2 = frames[i + 1];
      const span = b2.t - a.t || 1;
      const tt2 = Math.min(1, Math.max(0, (runTimeMs - a.t) / span));
      const x2 = a.x + (b2.x - a.x) * tt2;
      const z = a.z + (b2.z - a.z) * tt2;
      g.group.position.set(x2, 0, z);
      g.mesh.rotation.y += dt2 * 1.2;
      g.mesh.rotation.x = Math.sin(this.runTime * 1.7) * 0.15;
      const shattered = a.shattered === 1;
      const targetOpacity = shattered ? GHOST_OPACITY2 * 0.4 : GHOST_OPACITY2;
      g.material.opacity = MathUtils.lerp(g.material.opacity, targetOpacity, 1 - Math.exp(-8 * dt2));
    }
    for (let i = this.bursts.length - 1; i >= 0; i--) {
      const burst = this.bursts[i];
      burst.age += dt2;
      const positions = burst.points.geometry.getAttribute("position");
      for (let p = 0; p < positions.count; p++) {
        positions.setX(p, positions.getX(p) + burst.velocities[p * 3] * dt2);
        positions.setY(p, positions.getY(p) + burst.velocities[p * 3 + 1] * dt2);
        positions.setZ(p, positions.getZ(p) + burst.velocities[p * 3 + 2] * dt2);
      }
      positions.needsUpdate = true;
      burst.material.opacity = Math.max(0, 1 - burst.age / burst.lifetime);
      if (burst.age >= burst.lifetime) {
        this.scene.remove(burst.group);
        burst.points.geometry.dispose();
        burst.material.dispose();
        this.bursts.splice(i, 1);
      }
    }
  }
  spawnBurst(position, color) {
    const count = 24;
    const geo = new BufferGeometry();
    const positions = new Float32Array(count * 3);
    const velocities = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = position.x;
      positions[i * 3 + 1] = position.y;
      positions[i * 3 + 2] = position.z;
      const dir = new Vector3(
        Math.random() * 2 - 1,
        Math.random() * 2 - 1,
        Math.random() * 2 - 1
      ).normalize().multiplyScalar(3 + Math.random() * 3);
      velocities[i * 3] = dir.x;
      velocities[i * 3 + 1] = dir.y;
      velocities[i * 3 + 2] = dir.z;
    }
    geo.setAttribute("position", new BufferAttribute(positions, 3));
    const material = new PointsMaterial({
      color,
      size: 0.25,
      transparent: true,
      opacity: 1,
      depthWrite: false,
      blending: AdditiveBlending
    });
    const points = new Points(geo, material);
    const group = new Group();
    group.add(points);
    this.scene.add(group);
    this.bursts.push({
      group,
      points,
      material,
      velocities,
      age: 0,
      lifetime: 0.8
    });
  }
  /** Names of ghosts the player outlasted during the current run. */
  getBeatenNames() {
    return this.beatenNames.slice();
  }
  /** Hide all ghosts (e.g. during title / game over). Does not destroy them. */
  hideAll() {
    for (const g of this.ghosts) g.group.visible = false;
  }
  clear() {
    for (const g of this.ghosts) {
      this.scene.remove(g.group);
      g.mesh.geometry.dispose();
      g.material.dispose();
      if (g.nameMaterial.map) g.nameMaterial.map.dispose();
      g.nameMaterial.dispose();
    }
    this.ghosts = [];
    for (const b2 of this.bursts) {
      this.scene.remove(b2.group);
      b2.points.geometry.dispose();
      b2.material.dispose();
    }
    this.bursts = [];
  }
};
function makeNameTexture(name3, color) {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 64;
  const ctx2 = canvas.getContext("2d");
  ctx2.clearRect(0, 0, canvas.width, canvas.height);
  const hex = "#" + color.toString(16).padStart(6, "0");
  ctx2.font = "bold 36px 'Orbitron', monospace";
  ctx2.textAlign = "center";
  ctx2.textBaseline = "middle";
  ctx2.shadowColor = hex;
  ctx2.shadowBlur = 12;
  ctx2.fillStyle = hex;
  ctx2.fillText(name3.slice(0, 16).toUpperCase(), canvas.width / 2, canvas.height / 2);
  const tex = new CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

