      const outerColor = `hsla(${hueB}, 100%, 55%, ${0.26 + pulse * 0.16})`;
      shadow = `inset 0 0 20px ${innerColor}, inset 0 0 56px ${outerColor}, inset 0 0 96px rgba(255,255,255,${0.08 + pulse * 0.08})`;
